'use strict';
let sessionToken='';
async function atlasRequest(path,data){if(!sessionToken){const response=await fetch('/api/session');if(!response.ok)throw Error('Servizio non disponibile.');sessionToken=(await response.json()).token;}const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Atlas-Token':sessionToken},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error);return result;}
async function showDiagnostics(){const response=await fetch('/api/diagnostics');const data=await response.json();if(!response.ok)throw Error(data.error);$('#diagnostic-results').innerHTML=data.checks.map(c=>`<p><strong>${escapeHTML(c.name)} · ${c.ok?'OK':'Da controllare'}</strong><br>${escapeHTML(c.message)}</p>`).join('')+`<p>Bridge: ${data.bridge_installed?(data.bridge_current?'aggiornata':'aggiornamento disponibile'):'non installata'}</p>`;$('#settings-version').textContent='Isaac Atlas '+data.version;return data;}
$('#open-settings').addEventListener('click',async()=>{$('#settings-dialog').showModal();$('#settings-feedback').textContent='Rilevamento in corso…';try{const response=await fetch('/api/settings');const data=await response.json();if(response.ok){$('#save-directory').value=data.save_directory;$('#game-directory').value=data.game_directory;}await showDiagnostics();$('#settings-feedback').textContent='Lascia i percorsi vuoti per il rilevamento automatico.';}catch(e){$('#settings-feedback').textContent=e.message;}});
$('#close-settings').addEventListener('click',()=>$('#settings-dialog').close());
$('#save-settings').addEventListener('click',async()=>{const button=$('#save-settings');button.disabled=true;try{await atlasRequest('/api/settings',{save_directory:$('#save-directory').value,game_directory:$('#game-directory').value});$('#settings-feedback').textContent='Configurazione salvata. Ricarico il collegamento…';location.reload();}catch(e){$('#settings-feedback').textContent=e.message;}finally{button.disabled=false;}});
for(const [id,update] of [['install-bridge',false],['update-bridge',true]])$('#'+id).addEventListener('click',async()=>{if(!$('#game-closed').checked){$('#settings-feedback').textContent='Chiudi il gioco e conferma la casella prima di installare la Bridge.';return;}$('#'+id).disabled=true;try{const result=await atlasRequest('/api/bridge/install',{game_directory:$('#game-directory').value,update});$('#settings-feedback').textContent=result.message;await showDiagnostics();}catch(e){$('#settings-feedback').textContent=e.message;}finally{$('#'+id).disabled=false;}});
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#export-diagnostics').addEventListener('click',async()=>{try{downloadJSON(await showDiagnostics(),'isaac-atlas-diagnostics.json');}catch(e){$('#settings-feedback').textContent=e.message;}});
$('#export-pins').addEventListener('click',()=>{if(!progress)return;downloadJSON({format:'isaac-atlas-favourites',version:1,slot,ids:[...saved]},'isaac-atlas-preferiti-slot-'+slot+'.json');});
$('#import-pins').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(!progress)throw Error('Collega prima il salvataggio di destinazione.');if(file.size>32768)throw Error('File troppo grande.');const data=JSON.parse(await file.text());if(data.format!=='isaac-atlas-favourites'||data.version!==1||!Array.isArray(data.ids)||data.ids.length>641||data.ids.some(id=>!Number.isInteger(id)||!catalog.some(r=>r.id===id)))throw Error('File preferiti non valido.');for(const id of data.ids)saved.add(id);localStorage.setItem(pinKey(),JSON.stringify([...saved]));render();toast('Preferiti aggiunti allo slot '+slot+'.');}catch(error){toast(error.message);}finally{e.target.value='';}});
for(const id of ['save-directory','game-directory'])$('#browse-'+id).addEventListener('click',async()=>{try{if(!window.pywebview?.api){$('#settings-feedback').textContent='Nel browser incolla il percorso della cartella. Il selettore nativo è disponibile nell’app desktop.';$('#'+id).focus();return;}const path=await window.pywebview.api.choose_directory();if(path)$('#'+id).value=path;}catch{$('#settings-feedback').textContent='Selezione annullata o non disponibile.';}});
$('#compact-mode').addEventListener('click',async()=>{document.body.classList.toggle('compact-mode');const compact=document.body.classList.contains('compact-mode');$('#compact-mode').textContent=compact?'Vista completa':'Vista compatta';if(window.pywebview?.api)await window.pywebview.api.compact(compact);});
